package com.example.saxtrainer.core.designsystem.component

import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.vector.PathParser

/**
 * The notation glyphs, as outlines rather than as a font.
 *
 * Generated - do not edit by hand:
 *
 *     python tools/bravura_glyphs.py --kotlin
 *
 * The shapes come from Bravura 1.482 by Steinberg Media Technologies GmbH, under the SIL
 * Open Font License 1.1 with Reserved Font Name "Bravura". Only the outlines are used, as
 * vector artwork, which OFL-FAQ 1.1 allows without further condition; the font itself is
 * neither shipped nor depended on at runtime. See `tools/bravura_glyphs.py` for the
 * extraction, and `tools/notation-glyphs.svg` for what these shapes look like drawn.
 *
 * Everything is in staff spaces, with y running down from whatever the glyph is anchored
 * to - the G line for the clef, the note's own line or space for a head, an accidental or
 * a dot, the bottom staff line for a bar line. SMuFL registers glyphs that way, so a
 * shape drawn at the point it belongs to is already in the right place, at any size.
 */
internal object BravuraGlyphs {

    /** The G clef, anchored on the G line. */
    val gClef: Path by glyph(G_CLEF)

    /** A whole note's head: no stem, so no stem anchor. */
    val noteheadWhole: Path by glyph(NOTEHEAD_WHOLE)

    /** A half note's head, hollow. */
    val noteheadHalf: Path by glyph(NOTEHEAD_HALF)

    /** Every head shorter than a half, filled. */
    val noteheadBlack: Path by glyph(NOTEHEAD_BLACK)

    /** One flag, hanging from the top of an upward stem. */
    val flag8thUp: Path by glyph(FLAG_8TH_UP)

    /** One flag, rising from the foot of a downward stem. */
    val flag8thDown: Path by glyph(FLAG_8TH_DOWN)

    /** Two flags in one shape. */
    val flag16thUp: Path by glyph(FLAG_16TH_UP)

    /** Two flags in one shape. */
    val flag16thDown: Path by glyph(FLAG_16TH_DOWN)

    /** A sharp, centred on the note's own line. */
    val accidentalSharp: Path by glyph(ACCIDENTAL_SHARP)

    /** A flat; it reaches well above the note and little below it. */
    val accidentalFlat: Path by glyph(ACCIDENTAL_FLAT)

    /** A natural. */
    val accidentalNatural: Path by glyph(ACCIDENTAL_NATURAL)

    /** One augmentation dot. */
    val augmentationDot: Path by glyph(AUGMENTATION_DOT)

    /** A whole rest, hanging under the fourth line. */
    val restWhole: Path by glyph(REST_WHOLE)

    /** A half rest, sitting on the middle line. */
    val restHalf: Path by glyph(REST_HALF)

    /** A quarter rest, centred on the middle line. */
    val restQuarter: Path by glyph(REST_QUARTER)

    /** An eighth rest, centred on the middle line. */
    val rest8th: Path by glyph(REST_8TH)

    /** A sixteenth rest, centred on the middle line. */
    val rest16th: Path by glyph(REST_16TH)

    /** A thin bar line, four spaces tall from the bottom line. */
    val barlineSingle: Path by glyph(BARLINE_SINGLE)

    /** Two thin bar lines: the end of a section. */
    val barlineDouble: Path by glyph(BARLINE_DOUBLE)

    /** Thin then thick: the end of a piece. */
    val barlineFinal: Path by glyph(BARLINE_FINAL)

    /**
     * The ten digits a time signature is made of, indexed by the digit itself.
     *
     * A list rather than ten properties because a time signature is read off a number:
     * nothing here knows or cares whether that number is 4, 6 or 12.
     */
    val timeSignatureDigits: List<Path> by lazy(LazyThreadSafetyMode.NONE) {
        TIME_SIGNATURE_DATA.map { PathParser().parsePathString(it).toPath() }
    }

    /** How wide each of those digits is, in staff spaces. */
    val timeSignatureDigitWidths: List<Float> = listOf(
        1.8f, 1.256f, 1.704f, 1.604f, 1.8f, 1.532f, 1.656f, 1.684f, 1.664f, 1.656f,
    )

    /** Half a digit's height: they are all two staff spaces tall, centred on a line. */
    const val TIME_SIGNATURE_HALF_HEIGHT: Float = 1f

    // --- metrics, from the font's own bounding boxes and anchors ---------------------

    /** Head widths, so a head can be centred on the position the layout gives it. */
    const val NOTEHEAD_WIDTH: Float = 1.18f
    const val NOTEHEAD_WHOLE_WIDTH: Float = 1.688f

    /**
     * How far from the head's centre a stem meets it.
     *
     * A stem drawn from the centre would show through a hollow head; from here it only
     * touches the outline, which is what the anchor is for.
     */
    const val STEM_ATTACH_SPACES: Float = 0.168f

    /** Where a flag's own attachment point sits, relative to the end of the stem. */
    const val FLAG_8_UP_ATTACH: Float = 0.04f
    const val FLAG_8_DOWN_ATTACH: Float = -0.132f
    const val FLAG_16_UP_ATTACH: Float = 0.088f
    const val FLAG_16_DOWN_ATTACH: Float = -0.128f

    /** Accidental widths, so they can be hung to the left of the head by their edge. */
    const val SHARP_WIDTH: Float = 0.996f
    const val FLAT_WIDTH: Float = 0.904f
    const val NATURAL_WIDTH: Float = 0.672f
    const val DOT_WIDTH: Float = 0.4f

    /** Rest widths, so a rest can be centred on the position the layout gives it. */
    const val REST_WHOLE_WIDTH: Float = 1.128f
    const val REST_HALF_WIDTH: Float = 1.128f
    const val REST_QUARTER_WIDTH: Float = 1.08f
    const val REST_8TH_WIDTH: Float = 0.988f
    const val REST_16TH_WIDTH: Float = 1.28f

    /**
     * How far a rest reaches above and below the line it is registered on, in steps.
     *
     * A quarter rest is nearly three spaces tall, so a staff has to make room for it the
     * same way it makes room for a stem.
     */
    const val REST_TOP_STEP: Int = 3
    const val REST_BOTTOM_STEP: Int = -4

    /** Bar line widths, which is how far each one reaches right of where it is drawn. */
    const val BAR_LINE_SINGLE_WIDTH: Float = 0.16f
    const val BAR_LINE_DOUBLE_WIDTH: Float = 0.72f
    const val BAR_LINE_FINAL_WIDTH: Float = 1.06f

    /** How far the clef reaches, in staff steps, so a staff can make room for it. */
    const val CLEF_TOP_STEP: Int = 11
    const val CLEF_BOTTOM_STEP: Int = -4
    const val CLEF_WIDTH: Float = 2.684f

    // --- Bravura's engraving defaults, so the lines match the shapes -----------------

    const val STAFF_LINE_THICKNESS: Float = 0.13f
    const val STEM_THICKNESS: Float = 0.12f
    const val LEDGER_LINE_THICKNESS: Float = 0.16f
    const val LEDGER_LINE_EXTENSION: Float = 0.4f
    const val BEAM_THICKNESS: Float = 0.5f
    const val BEAM_SPACING: Float = 0.25f
    const val TIE_ENDPOINT_THICKNESS: Float = 0.1f
    const val TIE_MIDPOINT_THICKNESS: Float = 0.22f

    /** Parsed once each, on first use, and drawn through a transform ever after. */
    private fun glyph(data: String): Lazy<Path> =
        lazy(LazyThreadSafetyMode.NONE) { PathParser().parsePathString(data).toPath() }
}

